UPDATE message_chat
SET recall_status = '1',
    recall_time = #{recallTime},
    update_by = #{senderId},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND id = #{messageId}
  AND sender_type = #{senderType}
  AND sender_id = #{senderId}
  AND recall_status = '0'
  AND del_flag = '0'
